  teach('bio9.mitosis', {
    why: ['You grew from one cell, and cuts heal, because cells divide. Cancer is cell division out of control.', 'نشأت من خلية واحدة، وتلتئم الجروح لأن الخلايا تنقسم، والسرطان انقسام خرج عن السيطرة.'],
    idea: [['Mitosis copies a cell into two identical cells, each with the full set of chromosomes. It is for growth and repair.', 'الانقسام المتساوي ينسخ الخلية إلى خليتين متطابقتين في كل منهما العدد الكامل من الكروموسومات، وهو للنمو والإصلاح.'],
      ['Meiosis makes sex cells with half the chromosomes. When two join, the full number is restored.', 'الانقسام المنصف يصنع الخلايا الجنسية بنصف عدد الكروموسومات، وحين تتحد اثنتان يكتمل العدد.'],
      ['Human body cells have 46 chromosomes, in 23 pairs. Sex cells have 23.', 'خلايا جسم الإنسان فيها ٤٦ كروموسومًا في ٢٣ زوجًا، والخلايا الجنسية فيها ٢٣.']],
    g: function (r, lv) {
      if (lv === 1) { var c = r.pick([[['repairing a cut in the skin', 'إصلاح جرح في الجلد'], true], [['a child growing taller', 'نمو الطفل طولًا'], true], [['making sperm or egg cells', 'صنع الحيوانات المنوية أو البويضات'], false], [['replacing worn-out cells in the gut', 'استبدال خلايا الأمعاء البالية'], true]]);
        return { q: ['Which kind of cell division is used for ' + c[0][0] + '?', 'أي نوع من انقسام الخلايا يُستعمل في ' + c[0][1] + '؟'], o: c[1] ? [['Mitosis', 'الانقسام المتساوي'], ['Meiosis', 'الانقسام المنصف', 'Meiosis only makes sex cells.', 'المنصف يصنع الخلايا الجنسية فقط.'], ['Neither', 'لا هذا ولا ذاك', 'New cells come only from cell division.', 'الخلايا الجديدة لا تأتي إلا من الانقسام.']] : [['Meiosis', 'الانقسام المنصف'], ['Mitosis', 'الانقسام المتساوي', 'Mitosis keeps the full number. Sex cells need half.', 'المتساوي يحفظ العدد الكامل، والخلايا الجنسية تحتاج النصف.'], ['Neither', 'لا هذا ولا ذاك', 'New cells come only from cell division.', 'الخلايا الجديدة لا تأتي إلا من الانقسام.']],
          s: [w(['Growth and repair need identical copies', 'النمو والإصلاح يحتاجان نسخًا متطابقة'], ['These new cells need', 'هذه الخلايا الجديدة تحتاج'], c[1] ? ['the full set of chromosomes', 'العدد الكامل من الكروموسومات'] : ['half the chromosomes', 'نصف الكروموسومات'], '', [c[1] ? ['half the chromosomes', 'نصف الكروموسومات'] : ['the full set of chromosomes', 'العدد الكامل من الكروموسومات']])] }; }
      if (lv === 2) { var org = r.pick([[['a dog', 'الكلب'], 78], [['a cat', 'القط'], 38], [['a pea plant', 'نبات البازلاء'], 14], [['a horse', 'الحصان'], 64], [['a human', 'الإنسان'], 46]]), mei = r.bool();
        return { q: ['The body cells of ' + org[0][0] + ' have ' + org[1] + ' chromosomes. How many are in ' + (mei ? 'one of its sex cells' : 'each cell made by mitosis') + '?', 'خلايا جسم ' + org[0][1] + ' فيها ' + org[1] + ' كروموسومًا. كم كروموسومًا في ' + (mei ? 'إحدى خلاياه الجنسية' : 'كل خلية ناتجة عن الانقسام المتساوي') + '؟'], a: mei ? org[1] / 2 : org[1],
          s: mei ? [['Meiosis halves the number', 'المنصف ينصّف العدد', org[1] + ' ÷ 2 =', org[1] / 2]] : [w(['Mitosis makes identical copies', 'المتساوي يصنع نسخًا متطابقة'], ['The number stays', 'العدد يبقى'], ['the same', 'كما هو'], '', [['halved', 'نصفًا', 'Halving is meiosis.', 'التنصيف في المنصف.']]), ['So', 'إذن', 'Count:', org[1]]], miss: [[mei ? org[1] : org[1] / 2, mei ? 'Sex cells have half the chromosomes.' : 'Mitosis keeps the full number.', mei ? 'الخلايا الجنسية فيها نصف الكروموسومات.' : 'المتساوي يحفظ العدد الكامل.']] }; }
      var k = r.int(3, 8), N = Math.pow(2, k), lines = [], v = 1;
      for (var i = 0; i < Math.min(k, 3); i++) { lines.push([i ? null : 'Each division doubles the cells', i ? null : 'كل انقسام يضاعف الخلايا', v + ' × 2 =', v * 2]); v *= 2; }
      if (k > 3) lines.push(['Keep doubling, ' + k + ' times in all', 'استمر في المضاعفة، ' + k + ' مرات في المجموع', '2^' + k + ' =', N]);
      return { q: ['One cell divides by mitosis, then every new cell divides again, ' + k + ' times in all. How many cells are there?', 'تنقسم خلية انقسامًا متساويًا، ثم تنقسم كل خلية جديدة مرة أخرى، ' + cnt(k, 'مرة', 'مرتين', 'مرات', 'مرة') + ' في المجموع. كم خلية تصبح؟'], a: N, s: lines, miss: [[2 * k, 'Each round doubles the number. It does not add 2.', 'كل جولة تضاعف العدد، ولا تضيف ٢.']] };
    },
    trap: function () { return { q: ['A student compares mitosis and meiosis in humans. One line is wrong. Tap it.', 'طالب يقارن الانقسامين في الإنسان. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['Mitosis keeps all 46 chromosomes. Only meiosis halves them to 23.', 'المتساوي يحفظ الكروموسومات الـ٤٦ كلها، والمنصف وحده ينصفها إلى ٢٣.'], l: [['Body cells have 46 chromosomes', 'خلايا الجسم فيها ٤٦ كروموسومًا'], ['Mitosis makes cells with 23', 'المتساوي يصنع خلايا فيها ٢٣'], ['When egg and sperm join, there are 46 again', 'حين تتحد البويضة والحيوان المنوي يعود العدد ٤٦']] }; },
    explain: [['Why must sex cells have half the chromosomes?', 'لماذا يجب أن تحوي الخلايا الجنسية نصف الكروموسومات؟'], ['Two of them join, so the child ends up with the full number, half from each parent.', 'لأن اثنتين منها تتحدان، فيكتمل العدد في الطفل، نصفه من كل والد.'], ['Smaller cells swim faster.', 'الخلايا الأصغر تسبح أسرع.'], ['Chromosomes are too heavy.', 'الكروموسومات ثقيلة جدًا.']]
  });

  teach('bio9.plantresp', {
    why: ['Plants cannot walk to the light or the water, yet they reach both. Farmers and gardeners use their hormones every day.', 'لا يستطيع النبات أن يمشي إلى الضوء أو الماء، ومع ذلك يبلغهما، والمزارعون يستعملون هرموناته كل يوم.'],
    idea: [['Shoots grow towards light (phototropism). Roots grow down with gravity (gravitropism).', 'تنمو السيقان نحو الضوء (الانتحاء الضوئي)، وتنمو الجذور إلى الأسفل مع الجاذبية (الانتحاء الأرضي).'],
      ['A hormone called auxin controls this. In a shoot, auxin gathers on the shaded side and makes those cells grow longer, so the shoot bends towards the light.', 'يتحكم في ذلك هرمون الأكسين؛ ففي الساق يتجمع في الجانب المظلل ويجعل خلاياه تستطيل، فينحني الساق نحو الضوء.'],
      ['Growth rate = change in length ÷ time.', 'معدل النمو = التغير في الطول ÷ الزمن.']],
    g: function (r, lv) {
      if (lv === 1) { var c = r.pick([[['A shoot on a windowsill', 'ساق على حافة نافذة'], ['towards the light', 'نحو الضوء']], [['A root in the soil', 'جذر في التربة'], ['downwards, with gravity', 'إلى الأسفل مع الجاذبية']], [['A seedling\'s shoot in a dark box with one hole', 'ساق بادرة في صندوق مظلم فيه ثقب واحد'], ['towards the hole', 'نحو الثقب']]]), all = [['towards the light', 'نحو الضوء'], ['downwards, with gravity', 'إلى الأسفل مع الجاذبية'], ['towards the hole', 'نحو الثقب'], ['away from the light', 'بعيدًا عن الضوء']];
        return { q: [c[0][0] + ': which way does it grow?', c[0][1] + ': في أي اتجاه ينمو؟'], o: [[cap(c[1][0]), c[1][1]]].concat(all.filter(function (x) { return x[0] !== c[1][0] && !(c[1][0] === 'towards the hole' && x[0] === 'towards the light') && !(c[1][0] === 'towards the light' && x[0] === 'towards the hole'); }).slice(0, 2).map(function (x) { return [cap(x[0]), x[1]]; })),
          s: [w(['Shoots seek light, roots follow gravity', 'السيقان تطلب الضوء والجذور تتبع الجاذبية'], ['It grows', 'ينمو'], c[1], '', [['away from the light', 'بعيدًا عن الضوء']])] }; }
      if (lv === 2) return ask(r.pick([[['Light comes from the left. On which side of the shoot does auxin gather?', 'يأتي الضوء من اليسار. في أي جانب من الساق يتجمع الأكسين؟'], ['The right, the shaded side', 'اليمين، الجانب المظلل'], ['The left, the lit side', 'اليسار، الجانب المضاء', 'Auxin moves away from the light.', 'الأكسين يبتعد عن الضوء.'], ['Evenly on both sides', 'بالتساوي على الجانبين', 'Then the shoot would grow straight up.', 'لو كان كذلك لنما الساق مستقيمًا.'], ['Auxin moves to the shaded side', 'الأكسين ينتقل إلى الجانب المظلل']], [['What does auxin do to cells in a shoot?', 'ماذا يفعل الأكسين بخلايا الساق؟'], ['Makes them grow longer', 'يجعلها تستطيل'], ['Makes them die', 'يجعلها تموت', 'It makes them grow.', 'يجعلها تنمو.'], ['Turns them green', 'يجعلها خضراء', 'Chlorophyll makes them green.', 'اليخضور هو ما يجعلها خضراء.'], ['Auxin is a growth hormone', 'الأكسين هرمون نمو']]]));
      var d = r.pick([4, 5, 6, 8, 10]), rate = r.pick([2, 3, 4, 5]), l0 = r.int(10, 30), l1 = l0 + rate * d;
      return { q: ['A seedling grows from ' + l0 + ' mm to ' + l1 + ' mm in ' + d + ' days. What is its mean growth rate in mm per day?', 'تنمو بادرة من ' + l0 + ' mm إلى ' + l1 + ' mm في ' + cnt(d, 'يوم', 'يومين', 'أيام', 'يومًا') + '. ما متوسط معدل نموها بالمليمتر في اليوم؟'], a: rate,
        s: [['Growth', 'النمو', l1 + ' − ' + l0 + ' =', l1 - l0, 'mm'], ['Millimetres per day', 'مليمترات في اليوم', (l1 - l0) + ' ÷ ' + d + ' =', rate]], miss: [[n(l1 / d, 2), 'Use the growth, not the final length.', 'استعمل مقدار النمو لا الطول النهائي.']] };
    },
    trap: function () { return { q: ['A student explains why a shoot bends to the light. One line is wrong. Tap it.', 'طالب يفسر انحناء الساق نحو الضوء. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['Auxin gathers on the shaded side, so that side grows longer and the shoot bends towards the light.', 'يتجمع الأكسين في الجانب المظلل فيستطيل ذلك الجانب، فينحني الساق نحو الضوء.'], l: [['Light shines from one side', 'يسطع الضوء من جانب واحد'], ['Auxin gathers on the lit side', 'يتجمع الأكسين في الجانب المضاء'], ['The shaded side grows longer, so it bends', 'يستطيل الجانب المظلل فينحني']] }; },
    explain: [['Why do plants on a windowsill lean towards the glass?', 'لماذا تميل النباتات على حافة النافذة نحو الزجاج؟'], ['Auxin builds up on the shaded side, which grows faster, bending the shoot to the light.', 'يتراكم الأكسين في الجانب المظلل فينمو أسرع، فينحني الساق نحو الضوء.'], ['The glass pulls the plant.', 'الزجاج يجذب النبات.'], ['The side near the window dies.', 'الجانب القريب من النافذة يموت.']]
  });

  /* ---------- chemistry: patterns ---------- */
  var G1 = [['lithium', 'الليثيوم'], ['sodium', 'الصوديوم'], ['potassium', 'البوتاسيوم']], G7 = [['fluorine', 'الفلور'], ['chlorine', 'الكلور'], ['bromine', 'البروم'], ['iodine', 'اليود']];
  teach('che9.group1', {
    why: ['The periodic table is a pattern, and patterns let you predict. These two groups show it most clearly.', 'الجدول الدوري نمط، والأنماط تمكّنك من التوقع، وهاتان المجموعتان تُظهرانه أوضح ما يكون.'],
    idea: [['Group 1, the alkali metals, all have one outer electron. Going down the group they get more reactive, because that electron is further from the nucleus and easier to lose.', 'المجموعة ١، الفلزات القلوية، لكل منها إلكترون خارجي واحد، وتزداد نشاطًا كلما نزلنا، لأن ذلك الإلكترون أبعد عن النواة وأسهل فقدًا.'],
      ['Group 7, the halogens, have seven outer electrons. Going down they get less reactive, because it is harder to attract an extra electron from further away.', 'المجموعة ٧، الهالوجينات، لها سبعة إلكترونات خارجية، وتقل نشاطًا كلما نزلنا، لأن جذب إلكترون إضافي من بعد أصعب.'],
      ['A more reactive halogen displaces a less reactive one from its salt.', 'الهالوجين الأنشط يُزيح الأقل نشاطًا من ملحه.']],
    g: function (r, lv) {
      if (lv === 1) { var i = r.int(0, 1), j = r.int(i + 1, 2);
        return { q: ['Which reacts more violently with water: ' + G1[i][0] + ' or ' + G1[j][0] + '?', 'أيهما أعنف تفاعلًا مع الماء: ' + G1[i][1] + ' أم ' + G1[j][1] + '؟'], o: [[cap(G1[j][0]), G1[j][1]], [cap(G1[i][0]), G1[i][1], 'It is higher in group 1, so less reactive.', 'هو أعلى في المجموعة ١، فهو أقل نشاطًا.'], ['They react the same', 'يتفاعلان بالقدر نفسه', 'Reactivity changes down the group.', 'النشاط يتغير نزولًا في المجموعة.']],
          s: [w(['Group 1 gets more reactive going down', 'المجموعة ١ يزداد نشاطها نزولًا'], [cap(G1[j][0]) + ' is', G1[j][1]], ['lower in the group', 'أدنى في المجموعة'], '', [['higher in the group', 'أعلى في المجموعة']])] }; }
      if (lv === 2) { var a = r.int(0, 2), b = r.int(0, 2); while (b === a) b = r.int(0, 2); var go = a < b, A0 = G7[a + 1] || G7[a], X = [G7[1], G7[2], G7[3]];
        var h = X[a], s = X[b];
        return { q: ['Chlorine, bromine and iodine are in group 7, in that order. Will ' + h[0] + ' displace ' + s[0] + ' from a solution of its salt?', 'الكلور والبروم واليود في المجموعة ٧ بهذا الترتيب. هل يُزيح ' + h[1] + ' ' + s[1] + ' من محلول ملحه؟'], o: go ? [['Yes, it is more reactive', 'نعم، فهو أنشط'], ['No, it is less reactive', 'لا، فهو أقل نشاطًا', 'Halogens get less reactive going down, so ' + h[0] + ' is the more reactive.', 'الهالوجينات يقل نشاطها نزولًا، ف' + h[1] + ' هو الأنشط.'], ['Only if heated', 'فقط إذا سُخّن', 'It works in solution at room temperature.', 'يحدث في المحلول بحرارة الغرفة.']] : [['No, it is less reactive', 'لا، فهو أقل نشاطًا'], ['Yes, it is more reactive', 'نعم، فهو أنشط', 'Halogens get less reactive going down, so ' + h[0] + ' is the less reactive.', 'الهالوجينات يقل نشاطها نزولًا، ف' + h[1] + ' هو الأقل نشاطًا.'], ['Only if heated', 'فقط إذا سُخّن', 'Heating does not change the order.', 'التسخين لا يغيّر الترتيب.']],
          s: [w(['Group 7 gets less reactive going down', 'المجموعة ٧ يقل نشاطها نزولًا'], [cap(h[0]) + ' is', h[1]], go ? ['higher, so more reactive', 'أعلى فهو أنشط'] : ['lower, so less reactive', 'أدنى فهو أقل نشاطًا'], '', [go ? ['lower, so less reactive', 'أدنى فهو أقل نشاطًا'] : ['higher, so more reactive', 'أعلى فهو أنشط']])] }; }
      return ask(r.pick([[['Why is potassium more reactive than sodium?', 'لماذا البوتاسيوم أنشط من الصوديوم؟'], ['Its outer electron is further from the nucleus, so it is lost more easily', 'إلكترونه الخارجي أبعد عن النواة فيُفقد بسهولة أكبر'], ['It has more outer electrons', 'له إلكترونات خارجية أكثر', 'Both have one outer electron.', 'لكل منهما إلكترون خارجي واحد.'], ['It is lighter', 'هو أخف', 'Potassium is heavier, and mass is not the reason.', 'البوتاسيوم أثقل، والكتلة ليست السبب.'], ['Distance from the nucleus decides how easily an electron is lost', 'البعد عن النواة يحدد سهولة فقد الإلكترون']], [['Why is fluorine more reactive than chlorine?', 'لماذا الفلور أنشط من الكلور؟'], ['Its outer shell is closer to the nucleus, so it attracts an extra electron more strongly', 'غلافه الخارجي أقرب إلى النواة فيجذب إلكترونًا إضافيًا بقوة أكبر'], ['It has fewer outer electrons', 'له إلكترونات خارجية أقل', 'Both have seven.', 'لكل منهما سبعة.'], ['It is a metal', 'هو فلز', 'Halogens are non-metals.', 'الهالوجينات لافلزات.'], ['Halogens react by gaining an electron', 'الهالوجينات تتفاعل باكتساب إلكترون']]]));
    },
    trap: function () { return { q: ['A student describes group 1 metals. One line is wrong. Tap it.', 'طالب يصف فلزات المجموعة ١. سطر واحد خاطئ. انقر عليه.'], w: 1, why: ['Group 1 gets more reactive going down: potassium is more reactive than lithium.', 'المجموعة ١ يزداد نشاطها نزولًا: البوتاسيوم أنشط من الليثيوم.'], l: [['They all have one outer electron', 'لكل منها إلكترون خارجي واحد'], ['Lithium is the most reactive of lithium, sodium and potassium', 'الليثيوم أنشط الليثيوم والصوديوم والبوتاسيوم'], ['They react with water to make hydrogen', 'تتفاعل مع الماء فتعطي الهيدروجين']] }; },
    explain: [['Why are group 1 metals stored under oil?', 'لماذا تُحفظ فلزات المجموعة ١ تحت الزيت؟'], ['They react quickly with air and water, and oil keeps both away.', 'تتفاعل بسرعة مع الهواء والماء، والزيت يعزلها عنهما.'], ['Oil makes them more reactive.', 'الزيت يجعلها أنشط.'], ['They would melt in air.', 'تنصهر في الهواء.']]
  });

  var IONS = [['Na', 1, 'sodium', 'الصوديوم'], ['K', 1, 'potassium', 'البوتاسيوم'], ['Mg', 2, 'magnesium', 'المغنيسيوم'], ['Ca', 2, 'calcium', 'الكالسيوم'], ['Al', 3, 'aluminium', 'الألومنيوم']], ANI = [['Cl', 1, 'chloride', 'الكلوريد'], ['O', 2, 'oxide', 'الأكسيد'], ['Br', 1, 'bromide', 'البروميد'], ['S', 2, 'sulfide', 'الكبريتيد']];
  var SUP = function (q, s) { return (q > 1 ? '²³'[q - 2] : '') + s; };
  var SB = function (k) { return k > 1 ? '₂₃'[k - 2] : ''; };
  var gcd = function (a, b) { return b ? gcd(b, a % b) : a; };
